import { getMetaContent } from "helpers/meta_helpers"

const EMBEDDED_LOCAL_TIME = /\{\{local_time:(\w+):([^}]+)\}\}/g

export function signedDifferenceInDays(fromDate, toDate, timeZone = viewerTimeZone()) {
  return Math.round((beginningOfDay(toDate, timeZone) - beginningOfDay(fromDate, timeZone)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date, timeZone = viewerTimeZone()) {
  const { year, month, day } = datePartsInTimezone(date, timeZone)
  return new Date(Date.UTC(year, month - 1, day))
}

// The timezone the server rendered with (the `timezone` meta tag). Client day
// boundaries follow that instead of the browser's resolved timezone, which can
// differ in a PWA. Time words are still the viewer's: the cookie that sets this
// tag comes from their browser.
export function viewerTimeZone() {
  return getMetaContent("timezone") || Intl.DateTimeFormat().resolvedOptions().timeZone
}

export function formatLocalTime(date, format = "relative", options = {}) {
  const now = options.now || new Date()
  const timeZone = options.timeZone || viewerTimeZone()

  switch (format) {
    case "time":
      return formatTime(date, timeZone)
    case "short_date":
      return formatShortDate(date, now, timeZone)
    case "date":
      return formatDate(date, timeZone)
    case "weekday":
      return formatWeekday(date, timeZone)
    case "numeric":
      return formatNumeric(date, timeZone)
    case "full":
      return formatFull(date, timeZone)
    default:
      return formatRelative(date, now, timeZone)
  }
}

export function formatEmbeddedLocalTimes(text, options = {}) {
  if (!text) return text

  return text.replace(EMBEDDED_LOCAL_TIME, (_match, format, iso) => {
    const date = new Date(iso)
    if (Number.isNaN(date.getTime())) return iso

    return formatLocalTime(date, format, options)
  })
}

// Same calendar day shows the clock ("1:42 PM"). Yesterday, tomorrow, and the
// rest of the week are words ("yesterday", "in 3 days", "5 days ago"). Older
// past dates fall back to a short date ("Sep 12").
function formatRelative(date, now, timeZone) {
  const dayDiff = signedDifferenceInDays(now, date, timeZone)

  if (dayDiff === 0) {
    return date.getTime() > now.getTime() ? "today" : formatTime(date, timeZone)
  } else if (dayDiff === -1) {
    return "yesterday"
  } else if (dayDiff === 1) {
    return "tomorrow"
  } else if (dayDiff < -1 && dayDiff > -7) {
    return `${-dayDiff} days ago`
  } else if (dayDiff > 1) {
    return `in ${dayDiff} days`
  } else {
    return formatShortDate(date, now, timeZone)
  }
}

function formatTime(date, timeZone) {
  return formatWith(date, { hour: "numeric", minute: "2-digit", hour12: true }, timeZone)
}

function formatShortDate(date, now, timeZone) {
  const options = { month: "short", day: "numeric" }
  if (yearOf(date, timeZone) !== yearOf(now, timeZone)) options.year = "numeric"

  return formatWith(date, options, timeZone)
}

function formatDate(date, timeZone) {
  return formatWith(date, { month: "short", day: "numeric", year: "numeric" }, timeZone)
}

function formatWeekday(date, timeZone) {
  return formatWith(date, { weekday: "long", month: "long", day: "numeric" }, timeZone)
}

function formatNumeric(date, timeZone) {
  return formatWith(date, {
    month: "numeric",
    day: "numeric",
    year: "2-digit",
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }, timeZone)
}

function formatFull(date, timeZone) {
  return formatWith(date, {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
    hour12: true
  }, timeZone)
}

function formatWith(date, options, timeZone) {
  try {
    return normalizeSpaces(new Intl.DateTimeFormat("en-US", { ...options, timeZone }).format(date))
  } catch {
    return normalizeSpaces(new Intl.DateTimeFormat("en-US", options).format(date))
  }
}

function yearOf(date, timeZone) {
  return datePartsInTimezone(date, timeZone).year
}

function datePartsInTimezone(date, timeZone) {
  return dateFormatter(timeZone).formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

const dateFormatterCache = new Map()

function dateFormatter(timeZone) {
  const key = timeZone || ""

  if (!dateFormatterCache.has(key)) {
    dateFormatterCache.set(key, buildDateFormatter(timeZone))
  }

  return dateFormatterCache.get(key)
}

function buildDateFormatter(timeZone) {
  const options = { year: "numeric", month: "2-digit", day: "2-digit" }

  try {
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone })
  } catch {
    return new Intl.DateTimeFormat("en-US", options)
  }
}

function normalizeSpaces(text) {
  return text.replace(/[\u202f\u00a0]/g, " ")
}
