assertEqual(formatLocalTime(tomorrow, "relative", { now, timeZone: ny }), "tomorrow", "tomorrow")

const inThreeDays = new Date("2025-09-15T17:42:00Z")
assertEqual(formatLocalTime(inThreeDays, "relative", { now, timeZone: ny }), "in 3 days", "in 3 days")

const inThirtyDays = new Date("2025-10-12T17:42:00Z")
assertEqual(formatLocalTime(inThirtyDays, "relative", { now, timeZone: ny }), "in 30 days", "further future stays in days")

const laterToday = new Date("2025-09-12T22:00:00Z") // 6:00 PM EDT, now is 3:42 PM
assertEqual(formatLocalTime(laterToday, "relative", { now, timeZone: ny }), "today", "later today")

// Tokyo sees the same "two hours ago" instant on the next calendar morning
assertEqual(formatLocalTime(twoHoursAgo, "relative", { now, timeZone: tokyo }), "2:42 AM", "tokyo clock")
assertEqual(formatLocalTime(new Date("2025-09-12T10:00:00Z"), "relative", { now, timeZone: tokyo }), "yesterday", "tokyo previous day")

// Other formats stay timezone-aware and stable
assertEqual(formatLocalTime(twoHoursAgo, "time", { now, timeZone: ny }), "1:42 PM", "time format")
assertEqual(formatLocalTime(twoHoursAgo, "short_date", { now, timeZone: ny }), "Sep 12", "short date")
assertEqual(formatLocalTime(twoHoursAgo, "date", { now, timeZone: ny }), "Sep 12, 2025", "date format")
assertEqual(formatLocalTime(twoHoursAgo, "weekday", { now, timeZone: ny }), "Friday, September 12", "weekday format")
assertEqual(formatLocalTime(twoHoursAgo, "numeric", { now, timeZone: ny }), "9/12/25, 1:42 PM", "numeric format")
assertEqual(formatLocalTime(twoHoursAgo, "full", { now, timeZone: ny }), "Friday, September 12, 2025 at 1:42 PM", "full format")

// A short date near midnight shifts with the timezone
assertEqual(formatLocalTime(new Date("2025-09-12T03:30:00Z"), "short_date", { now, timeZone: ny }), "Sep 11", "short date previous evening in NY")
assertEqual(formatLocalTime(new Date("2025-09-12T03:30:00Z"), "short_date", { now, timeZone: tokyo }), "Sep 12", "short date already morning in Tokyo")

// Embedded placeholders used by native share/stamp descriptions
const embedded = "Added {{local_time:short_date:2025-09-12T17:42:00Z}} by David. Updated {{local_time:date:2024-01-02T15:00:00Z}}"
assertEqual(
  formatEmbeddedLocalTimes(embedded, { now, timeZone: ny }),
  "Added Sep 12 by David. Updated Jan 2, 2024",
  "embedded placeholders"
)
assertEqual(formatEmbeddedLocalTimes("no tokens", { now, timeZone: ny }), "no tokens", "plain text unchanged")
assertEqual(formatEmbeddedLocalTimes(null), null, "null text")

// Day difference still follows the supplied timezone (bubble controller contract)
assertEqual(
  signedDifferenceInDays(justAfterMidnight, lastNight, ny),
  -1,
  "signed day difference across midnight"
)
assertEqual(
  signedDifferenceInDays(justAfterMidnight, lastNight, "UTC"),
  0,
  "signed day difference stays zero in UTC"
)

// DST: spring forward is still one calendar day
const beforeSpring = new Date("2025-03-08T12:00:00Z")
const afterSpring = new Date("2025-03-09T12:00:00Z")
assertEqual(signedDifferenceInDays(beforeSpring, afterSpring, ny), 1, "dst spring forward is one day")
assertEqual(formatLocalTime(beforeSpring, "relative", { now: afterSpring, timeZone: ny }), "yesterday", "dst yesterday")

